#!/usr/bin/env bash
# One-click installer (Linux): downloads the latest Base Station Manager (Lokinya's build) and installs it.
#   curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/base-station-manager/HEAD/get.sh | bash
# Part of Lokinya's modified build (GPL-3.0). Generated by AI (Claude, Anthropic).
set -euo pipefail
REPO="lokinyauv-create/base-station-manager"
ASSET="base-station-manager-linux-x86_64.tar.gz"
DEST="${XDG_DATA_HOME:-$HOME/.local/share}/base-station-manager"
APPS="${XDG_DATA_HOME:-$HOME/.local/share}/applications"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT

echo "Downloading Base Station Manager… / Завантажую Керування базовими станціями…"
curl -fL --retry 2 -o "$T/$ASSET" "https://github.com/$REPO/releases/latest/download/$ASSET"
mkdir -p "$T/x" && tar -xzf "$T/$ASSET" -C "$T/x"

pkill -x base-station-manager 2>/dev/null && sleep 2 || true
rm -rf "$DEST" && mkdir -p "$(dirname "$DEST")" && mv "$T/x" "$DEST"
mkdir -p "$HOME/.local/bin" "$APPS"
ln -sf "$DEST/base-station-manager" "$HOME/.local/bin/base-station-manager"
cat > "$APPS/base-station-manager.desktop" <<DESKTOP
[Desktop Entry]
Type=Application
Name=Base Station Manager
Name[uk]=Керування базовими станціями
Comment=Turns SteamVR base stations on and off over Bluetooth
Comment[uk]=Вмикає й вимикає базові станції SteamVR через Bluetooth
Exec=$DEST/base-station-manager
Path=$DEST
Icon=$DEST/icon.png
Terminal=false
Categories=Game;Utility;
DESKTOP

if ! ldconfig -p 2>/dev/null | grep -q libwebkit2gtk-4.1; then
    echo "⚠ WebKitGTK 4.1 is missing / бракує WebKitGTK 4.1:"
    echo "  Fedora: sudo dnf install webkit2gtk4.1    Debian/Ubuntu: sudo apt install libwebkit2gtk-4.1-0"
fi
echo "Installed $(cat "$DEST/VERSION") → $DEST / Встановлено."
